55.2},"rules":["Each two-week cycle: mock on day 1, forensic review on day 2, fixes, then timed modules at the end of the second week.","Two fix targets per cycle, chosen by (misses × official domain weight).","Clear the Reviews queue at least four days a week.","Re-solve every Notebook entry two days after logging it."],"phases":[{"label":"Cycle 1: foundations","weeks":[1,2],"goal":"Baseline mock; conventions and linear algebra to automatic; Desmos basics."},{"label":"Cycle 2: core skills","weeks":[3,4],"goal":"Evidence and data in R&W; quadratics, exponentials and functions in Math."},{"label":"Cycle 3: reasoning and applications","weeks":[5,6],"goal":"Words in context, structure, cross-text; data analysis, geometry and trigonometry."},{"label":"Cycle 4: hard modules and taper","weeks":[7,8],"goal":"Hard-only trap families, final full test, logistics and rest."}],"modules":["sat-essentials","reading-writing-information-ideas","reading-writing-craft-structure","reading-writing-expression-of-ideas","reading-writing-conventions","math-algebra","math-advanced-math","math-problem-solving-data-analysis","math-geometry-trigonometry","desmos-and-calculator-strategy","pacing-and-adaptive-modules","test-day-guide"],"guides":["guide-1200-to-1400-roadmap","guide-rw-hard-module-traps","guide-math-hard-module-traps","guide-desmos-power-moves","guide-final-14-days"],"weeks":[{"week":1,"label":"Week 1: Baseline and conventions","focus":["Baseline mock","Forensic review","Boundaries","Linear equations"],"hours":7,"days":[{"day":1,"weekday":"Mon","minutes":60,"tasks":["Read SAT Essentials — format, timing and scoring (/sat-essentials), 30 min","Read Pacing and Adaptive Modules — how the second module is chosen (/pacing-and-adaptive-modules), 30 min"]},{"day":2,"weekday":"Tue","minutes":30,"tasks":["Read 20 minutes of dense nonfiction (science, history, economics) and summarise each article's claim in one sentence","Clear due Reviews (https://practice.sat.schood.online/reviews), 10 