":4.7,"max":8.1,"total":38.4},"split":{"primary":"math","maintenance":"reading_writing"},"rules":["Math domains in order of official weight: Algebra and Advanced Math (about 35% each) before Problem-Solving and Data Analysis and Geometry and Trigonometry (about 15% each).","Every Math session ends with at least one question solved two ways: algebra and Desmos.","Two short R&W maintenance sessions a week; never skip them.","Full mock at the start of weeks 1, 3 and 5; timed Math module every week."],"phases":[{"label":"Algebra to automatic","weeks":[1,2],"goal":"Linear equations, functions, systems and inequalities; Desmos graphing routines."},{"label":"Advanced Math","weeks":[3,4],"goal":"Quadratics, exponentials, functions and equivalent expressions; parameters with sliders."},{"label":"Data, geometry and hard modules","weeks":[5,6],"goal":"Smaller domains, hard-module traps, SPR precision."}],"modules":["math-algebra","math-advanced-math","math-problem-solving-data-analysis","math-geometry-trigonometry","desmos-and-calculator-strategy","pacing-and-adaptive-modules"],"guides":["guide-desmos-power-moves","guide-math-hard-module-traps"],"weeks":[{"week":1,"label":"Week 1: Baseline and linear algebra","focus":["Baseline mock","Linear equations","Linear functions","Desmos graphing"],"hours":8.1,"days":[{"day":1,"weekday":"Mon","minutes":180,"tasks":["Full timed mock in the SAT simulator (https://sat.schood.online) at your real test time; one sitting with a 10-minute break"]},{"day":2,"weekday":"Tue","minutes":90,"tasks":["Forensic review of the mock: re-solve each missed, guessed and slow question before reading the explanation; assign cause codes C/P/T/X/G; name the trap; write a rule sentence","Math misses by skill; mark which were C, P, T, X"]},{"day":3,"weekday":"Wed","minutes":60,"tasks":["Read Math: Algebra — linear equations in one and two variables (/math-algebra), 20 min","SAT Practice Bank: 20 medium questions in Algebra → Linear equations (https://practice.sat.schood.online/bank); review every miss","Log misses and guesses in the Notebook with a cause code and a rule sentence (https://practice.sat.schood.online/notebook)"]},{"day":4,"weekday":"Thu","minutes":35,"tasks":["SAT Practice Bank: 12 medium questions in Standard English Conventions (https://practice.sat.schood.online/bank); review every miss","Clear due Reviews (https://practice.sat.schood.online/reviews), 10 min"]},{"day":5,"weekday":"Fri","minutes":60,"tasks":["Read Math: Algebra — linear functions: slope, intercept, interpretation (/math-algebra), 20 min","SAT Practice Bank: 20 medium questions in Algebra → Linear functions (https://practice.sat.schood.online/bank); review every miss"]},{"day":6,"weekday":"Sat","minutes":60,"tasks":["Read Desmos and Calculator Strategy — graphing both sides and intersections (/desmos-and-calculator-strategy), 25 min","SAT Practice Bank: 12 medium questions in Algebra, solved twice: algebra and Desmos (https://practice.sat.schood.online/bank); review every miss","Re-solve Notebook entries from the last 2–3 days without notes; close only correct re-solves"]},{"day":7,"weekday":"Sun","minutes":0,"tasks":["Rest day: no SAT work. Optional 20 minutes of reading nonfiction you enjoy"]}],"checkpoint":"Pass: Math misses classified; linear-equation accuracy rising in the Bank."},{"week":2,"label":"Week 2: Systems and inequalities","focus":["Systems of equations","Linear inequalities","Parameter basics","Timed Math module"],"hours":5,"days":[{"day":1,"weekday":"Mon","minutes":60,"tasks":["Read Math: Algebra — systems: one, none or infinitely many solutions (/math-algebra), 20 min","SAT Practice Bank: 20 medium questions in Algebra → Systems of linear equations (https://practice.sat.schood.online/bank); review every miss"]},{"day":2,"weekday":"Tue","minutes":35,"tasks":["SAT Practice Bank: 12 medium questions in Information and Ideas (https://practice.sat.schood.online/bank); review every miss","Clear due Reviews (https://practice.sat.schood.online/reviews), 10 min"]},{"day":3,"weekday":"Wed","minutes":60,"tasks":["Read Math: Algebra — linear inequalities (/math-algebra), 15 min","SAT Practice Bank: 15 medium questions in Algebra → Linear inequalities (https://practice.sat.schood.online/bank); review every miss","Read Desmos Power Moves (premium) — Move 5: inequalities and test points (/guide-desmos-power-moves), 15 min"]},{"day":4,"weekday":"Thu","minutes":60,"tasks":["Read Desmos Power Moves (premium) — Moves 3–4: sliders and no-solution systems (/guide-desmos-power-moves), 20 min","SAT Practice Bank: 15 hard questions in Algebra → Systems of linear equations (parameters) (https://practice.sat.schood.online/bank); review every miss"]},{"day":5,"weekday":"Fri","minutes":40,"tasks":["Timed Math module set: 22 mixed Math questions in 35 minutes from the SAT Practice Bank, timer on, Desmos allowed"]},{"day":6,"weekday":"Sat","minutes":45,"tasks":["Re-solve Notebook entries from weeks 1–2 without notes; close only correct re-solves","Clear due Reviews (https://practice.sat.schood.online/reviews), 15 min","Checkpoint: Algebra misses in the timed set vs the baseline mock"]},{"day":7,"weekday":"Sun","minutes":0,"tasks":["Rest day: no SAT work. Optional 20 minutes of reading nonfiction you enjoy"]}],"checkpoint":"Pass: in the timed Math set, Algebra misses are rare. If not, repeat week 2 days 1 and 4 before moving on."},{"week":3,"label":"Week 3: Quadratics and nonlinear systems","focus":["Mock 2","Quadratics","Discriminant","Nonlinear systems"],"hours":7.8,"days":[{"day":1,"weekday":"Mon","minutes":180,"tasks":["Full official Bluebook practice test (one you have not taken) at your real test time; one sitting with a 10-minute break"]},{"day":2,"weekday":"Tue","minutes":90,"tasks":["Forensic review of the mock: re-solve each missed, guessed and slow question before reading the explanation; assign cause codes C/P/T/X/G; name the trap; write a rule sentence","Compare Math with mock 1 by domain"]},{"day":3,"