"tasks":["SPR clinic: 15 student-produced response questions; write the exact entry before typing it, following the Bluebook entry rules","SAT Practice Bank: 10 hard questions in Geometry and Trigonometry and Problem-Solving and Data Analysis (https://practice.sat.schood.online/bank); review every miss"]},{"day":4,"weekday":"Thu","minutes":40,"tasks":["Timed Math module set: 22 mixed Math questions in 35 minutes from the SAT Practice Bank, timer on, Desmos allowed"]},{"day":5,"weekday":"Fri","minutes":40,"tasks":["Timed Math module set: 22 mixed Math questions in 35 minutes from the SAT Practice Bank, timer on, Desmos allowed","Use a different question set from day 4"]},{"day":6,"weekday":"Sat","minutes":45,"tasks":["Re-solve Notebook entries from the whole plan without notes; close only correct re-solves","Decide the next plan: Eight-Week Standard (/plans/eight-week-standard) for continued balance, or the Four-Week Sprint (/plans/four-week-sprint) if a test is close"]},{"day":7,"weekday":"Sun","minutes":0,"tasks":["Rest day: no SAT work. Optional 20 minutes of reading nonfiction you enjoy"]}],"checkpoint":"Pass: two timed Math modules with few misses and no SPR entry errors."}],"checkpoints":[{"week":2,"title":"Algebra secure","pass_rule":"Algebra misses rare in a timed Math set.","if_not":"Repeat week 2 before Advanced Math."},{"week":4,"title":"Advanced Math secure","pass_rule":"Advanced Math misses fall clearly from mock 2.","if_not":"Extend weeks 3–4 by one week before data and geometry."},{"week":6,"title":"Section ready","pass_rule":"Two clean timed Math modules; SPR entries correct.","if_not":"Repeat week 6 with new question sets."}]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161100_sat_playbook_plan_templates","content_revision":"sat-pb-premium-2026-10-v1","source_file":"content/sat-playbook/plans/math-priority.json","weekly_hours":{"min":4.7,"max":8.1,"total":38.4},"modules":["math-algebra","math-advanced-math","math-problem-solving-data-analysis","mat